package com.amar.slackclone.typing;import com.amar.slackclone.channel.*;import com.amar.slackclone.conversation.*;import com.amar.slackclone.user.*;import org.springframework.messaging.handler.annotation.*;import org.springframework.messaging.simp.SimpMessagingTemplate;import org.springframework.security.core.Authentication;import org.springframework.stereotype.Controller;import java.time.OffsetDateTime;
@Controller public class TypingWebSocketController{private final ChannelAccessService channels;private final ConversationAccessService conversations;private final ConversationParticipantRepository participants;private final UserRepository users;private final SimpMessagingTemplate broker;public TypingWebSocketController(ChannelAccessService c,ConversationAccessService co,ConversationParticipantRepository p,UserRepository u,SimpMessagingTemplate b){channels=c;conversations=co;participants=p;users=u;broker=b;}
@MessageMapping("/workspaces/{workspaceId}/channels/{channelId}/typing")public void channel(@DestinationVariable Long workspaceId,@DestinationVariable Long channelId,@Payload TypingRequest r,Authentication a){channels.validateChannelAccess(workspaceId,channelId,a.getName());User u=users.findByEmailIgnoreCase(a.getName()).orElseThrow();broker.convertAndSend("/topic/workspaces/"+workspaceId+"/channels/"+channelId+"/typing",new TypingEvent("CHANNEL",channelId,u.getId(),u.getDisplayName(),r.typing(),OffsetDateTime.now()));}
@MessageMapping("/conversations/{id}/typing")public void conversation(@DestinationVariable Long id,@Payload TypingRequest r,Authentication a){var actor=conversations.requireParticipant(id,a.getName());TypingEvent event=new TypingEvent("CONVERSATION",id,actor.getUser().getId(),actor.getUser().getDisplayName(),r.typing(),OffsetDateTime.now());participants.findUserIds(id).stream().filter(uid->!uid.equals(actor.getUser().getId())).forEach(uid->broker.convertAndSend("/topic/users/"+uid+"/conversations/"+id+"/typing",event));}}
